using System.Reflection;using UnityEngine;using UnityEditor;
public static class VerifyCashAudio{public static object Main(){var screen=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GameCanvas.prefab").GetComponentInChildren<SellingScreen>(true);var f=BindingFlags.Instance|BindingFlags.NonPublic;var clip=(AudioClip)typeof(SellingScreen).GetField("cashInClip",f).GetValue(screen);var group=(UnityEngine.Audio.AudioMixerGroup)typeof(SellingScreen).GetField("cashInMixerGroup",f).GetValue(screen);if(clip==null||group==null)throw new System.Exception("Missing cash-in binding");GlobalManager.PlaySound3D(clip,Vector3.zero,.8f,0,group);var go=GameObject.Find("TempAudio_"+clip.name);try{var source=go.GetComponent<AudioSource>();return new{clip=clip.name,mixer=group.name,source.isPlaying,source.spatialBlend,source.volume};}finally{Object.DestroyImmediate(go);}}}
